  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `daily_rec_user_date_rank_key`(`user_id` ASC, `recommend_date` ASC, `rank` ASC) USING BTREE,
  INDEX `daily_rec_user_id_idx`(`user_id` ASC) USING BTREE,
  INDEX `daily_rec_track_id_idx`(`track_id` ASC) USING BTREE,
  INDEX `daily_rec_date_idx`(`recommend_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 935 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

