INSERT INTO `track_review_records` VALUES (2071805851582062593, 2070902039702814722, 'Kill This Love', 'Black Pink', 'Kill This Love', '﻿[id:$0DE16514]\n[ar:Henry Young/Ashley Alisha]\n[ti:One More Last Time]\n[by:]\n[hash:baa1d4830b9d772e4eeb49e753162fac]\n[al:One More Last Time]\n[sign:]\n[qq:]\n[total:0]\n[offset:0]\n[language:]\n[manualoffset:0]\n[00:00.11]Henry Young、Ashley Alisha - One More Last Time\n[00:01.02]Lyrics by：Ashley Yoon\n[00:01.08]Composed by：Henry Song\n[00:01.15]남아있는 너의 온기와 너만의 향기\n[00:08.49]함께 있던 그 같은 공간도\n[00:12.02]난 지우고 있어\n[00:15.16]All I can do is try\n[00:16.97]우리만에 시간\n[00:18.85]뒤돌려봐도 없어지지는 않아\n[00:22.50]따뜻한 그 미소\n[00:24.36]너무 좋았던 말투\n[00:26.27]두 눈을 감아봐도\n[00:28.00]Don\'t wanna let you\n[00:29.56]Go baby\n[00:31.24]빗속에 너와\n[00:33.02]It\'s ooh raining\n[00:34.97]갇혀있어\n[00:36.42]널 닮은 사람 아무리 찾아도\n[00:40.44]Thinking \'bout you yeah\n[00:42.05]Only you 너만 보여\n[00:44.76]널 한번 붙잡아 봐\n[00:46.23]One more last time\n[00:48.34]바람이 불어와 모두 버리기엔\n[00:52.08]아까운 추억들 기억해봐\n[00:55.47]영원히 기다려줄게 my baby\n[00:59.70]차가워지는 너의 마음\n[01:01.50]상처만 남긴 너만 보면\n[01:03.68]먼저 말하고 싶은 내 goodbye\n[01:07.04]길을 잃어 어쩔 수가 없어\n[01:09.17]그만하고 싶어도 난 ooh\n[01:14.24]All I can do is try\n[01:15.95]우리만에 시간\n[01:17.79]뒤돌려봐도 없어지지는 않아\n[01:21.53]따뜻한 그 미소\n[01:23.30]너무 좋았던 말투\n[01:25.24]두 눈을 감아봐도\n[01:27.16]Don\'t wanna let you go baby\n[01:30.29]빗속에 너와\n[01:32.07]It\'s ooh raining\n[01:33.99]갇혀있어\n[01:35.58]널 닮은 사람 아무리 찾아도\n[01:39.47]Thinking \'bout you yeah\n[01:41.10]Only you 너만 보여\n[01:43.92]널 한번 붙잡아 봐\n[01:45.44]One more last time\n[01:47.45]바람이 불어와 모두 버리기엔\n[01:51.05]아까운 추억들 기억해봐\n[01:54.62]영원히 기다려줄게 my baby', 1, 100, '', '{\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":null},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":null},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":null},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":100,