INSERT INTO `track_review_records` VALUES (2071857488707072001, 2071857485276131330, '一台独立服务器', 'Ed Sheeran, The Weeknd, Olly Murs ', 'New Jeans 01', '﻿[id:$0B71B6EE]\n[ar:Aimer (エメ)]\n[ti:Ref:rain (《恋如雨止》TV动画片尾曲)]\n[by:]\n[hash:]\n[al:Penny Rain]\n[sign:]\n[qq:]\n[total:0]\n[offset:0]\n[language:]\n[manualoffset:0]\n[00:00.00]Ref:rain - Aimer (エメ)\n[00:02.28]词：aimerrhythm\n[00:04.56]曲：飛内将大\n[00:06.85]Raining\n[00:07.89]夏の午後に\n[00:09.86]通り雨傘の下\n[00:12.91]Kissing濡れた頬に\n[00:15.97]そっと口づけた\n[00:19.87]あの季節に\n[00:23.09]まだ焦がれている\n[00:31.54]Miss you窓の外に\n[00:34.37]遠ざかる景色たち\n[00:37.61]Breezing虹が見えた\n[00:40.43]すぐに消えそうで\n[00:44.47]雨明日は降らなければいい\n[00:55.00]何も手につかずに\n[00:58.08]上の空の日々\n[01:01.14]Nothing but you\'re the part of me\n[01:06.16]まだ足りなくて\n[01:08.98]まだ消えなくて\n[01:12.20]重ねた手のひらから幼さが\n[01:18.40]What a good thing we lose\n[01:21.43]What a bad thing we knew\n[01:24.55]そんなフレーズに濡れてく\n[01:28.13]雨の中\n[01:30.68]ただ足りなくて\n[01:33.67]まだ言えなくて\n[01:36.81]数えた日の夢からさよならが\n[01:43.01]What a good thing we lose\n[01:46.08]What a bad thing we knew\n[01:49.16]触れられずにいれたら\n[01:52.25]笑えたかな?\n[01:57.69]Calling白い息が\n[02:00.64]舞いあがる空の下\n[02:03.72]Freezing強い風に\n[02:06.72]少しかじかんだ手と\n[02:12.12]弱さをポケットの中に\n[02:21.03]どこを見渡しても\n[02:24.23]通り過ぎた日々\n[02:27.20]Nothing but you\'re the part of me\n[02:32.13]また触れたくて\n[02:35.12]ただ眩しくて\n[02:38.35]思わず目をそらした優しさに\n[02:44.60]I wanna sleep in your feel\n[02:47.57]I wanna see you in the deep\n[02:50.65]そんなフレーズを\n[02:52.54]並べた詩を今\n[02:56.89]あの帰り道\n[02:59.75]バスに揺られて\n[03:03.01]叶うはずもない様な夢を見た\n[03:09.13]I wanna sleep in your feel\n[03:12.17]I wanna see you in the deep\n[03:15.26]繰りかえす季節に\n[03:18.37]慣れないまま\n[03:23.27]もう少しくらい\n[03:27.63]大人でいれたら\n[03:29.79]何て言えただろう?\n[03:38.34]まだ足りなくて\n[03:41.35]まだ消えなくて\n[03:44.49]重ねた手のひらから幼さが\n[03:50.69]What a good thing we lose\n[03:53.74]What a bad thing we knew\n[03:56.85]そんなフレーズに濡れてく\n[04:00.22]雨の中\n[04:03.02]ただ足りなくて\n[04:05.84]まだ言えなくて\n[04:09.13]数えた日の夢からさよならが\n[04:15.29]What a good thing we lose\n[04:18.35]What a bad thing we knew\n[04:21.53]触れられずにいれたら\n[04:24.57]笑えたかな?', 1, 100, '', '{\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":null},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":null},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":null},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":null}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":100,\"failReasons\":\"\"}}', NULL, 4, 1, 1, NULL, '2026-06-30 15:25:17', '2026-06-30 15:24:53', '2026-06-30 15:25:05');
