INSERT INTO `track_review_records` VALUES (2071879889654276097, 2071877056216887297, '打上花火', 'Kenshi Yonezu', '米津玄师曲库', '﻿[id:$1A11DE11]\n[ar:HUNTR/X/EJAE (김은재)/AUDREY NUNA/REI AMI]\n[ti:Takedown (《kpop猎魔女团》电影插曲)]\n[by:]\n[hash:]\n[al:KPop Demon Hunters (Soundtrack from the Netflix Film) (kpop猎魔女团 电影原声带)]\n[sign:]\n[qq:]\n[total:0]\n[offset:0]\n[language:]\n[manualoffset:0]\n[00:00.00]Takedown - HUNTR/X/EJAE/AUDREY NUNA/REI AMI/KPop Demon Hunters Cast\n[00:00.25]Lyrics by：Lindgren\n[00:00.50]Composed by：Lindgren\n[00:00.75]Produced by：Lindgren/Ian Eisendrath\n[00:01.00]Takedown takedown\n[00:02.68]Takedown down down down\n[00:03.99]HUNTR/X girls to the world\n[00:05.63]Takedown takedown\n[00:06.11]Takedown down down down\n[00:06.61]It\'s a takedown\n[00:08.10]So sweet so easy on the eyes\n[00:09.85]But hideous on the inside\n[00:11.49]Whole life spreading lies but you can\'t hide baby nice try\n[00:14.71]I\'m \'bout to switch up these vibes\n[00:16.42]I finally opened my eyes\n[00:18.39]It\'s time to kick you straight back into the night\n[00:21.18]\'Cause I see your real face and it\'s ugly as sin\n[00:24.54]Time to put you in your place \'cause you\'re rotten within\n[00:28.01]When your patterns start to show\n[00:29.50]It makes the hatred wanna grow outta my veins\n[00:33.54]I don\'t think you\'re ready for the takedown\n[00:37.01]Break you into pieces in a world of pain \'cause you\'re all the same\n[00:41.54]Yeah it\'s a takedown a demon with no feelings\n[00:45.21]Don\'t deserve to live it\'s so obvious\n[00:48.96]I\'ma gear up and take you down oh\n[00:52.21]Da-da-da down\n[00:53.33]It\'s a takedown oh\n[00:55.61]Da-da-da down\n[00:56.67]I\'ma take it down oh\n[00:59.06]Da-da-da down\n[01:00.14]It\'s a takedown oh\n[01:02.72]Da-da-da down\n[01:03.38]Take it down\n[01:04.16]It\'s a takedown I\'ma take you out you break down like \"What?\"\n[01:07.64]It\'s a takedown I\'ma take you out and I ain\'t gonna stop\n[01:11.02]정신을 놓고 널 짓밟고 칼을 새겨놔\n[01:14.35]You\'ll be beggin\' and cryin\' all of you dyin\'\n[01:16.50]Never miss my shot\n[01:17.71]When your patterns start to show\n[01:19.21]It makes the hatred wanna grow out of my veins\n[01:23.29]I don\'t think you\'re ready for the takedown\n[01:26.68]당당하게 어둠 앞에 다가서\n[01:29.69]다 무너뜨려\n[01:31.29]Yeah it\'s a takedown a demon with no feelings\n[01:34.85]Don\'t deserve to live it\'s so obvious\n[01:38.67]I\'ma gear up and take you down oh\n[01:41.97]Da-da-da down\n[01:43.02]It\'s a takedown oh\n[01:45.38]Da-da-da down\n[01:46.40]I\'ma take it down\n[01:47.52]Oh watch me do it yeah\n[01:48.98]Da-da-da down ooh\n[01:49.86]It\'s a takedown oh\n[01:52.16]Da-da-da down ooh\n[01:55.03]Oh you\'re the master of illusion\n[01:58.82]나를 속이려 하지마\n[02:01.84]Look at all the masses that you\'re foolin\'\n[02:05.75]But they\'ll turn on you soon so how?\n[02:08.71]How can you sleep or live with yourself?\n[02:11.91]A broken soul trapped in a nastiest shell\n[02:15.37]영혼 없는 네 목숨을 끊으러\n[02:20.53]And watch you die\n[02:24.52]You can try but you can\'t hide\n[02:26.44]It\'s a takedown I\'ma take you out you break down like \"What?\"\n[02:29.90]It\'s a takedown I\'ma take you out and I ain\'t gonna stop\n[02:33.31]I\'ma cut you open lose control then rip out your heart\n[02:36.56]You\'ll be beggin\' and cryin\' all of you dyin\'\n[02:38.69]I\'ma gear up and take you down oh\n[02:41.93]Da-da-da down ah\n[02:43.01]It\'s a takedown oh\n[02:45.39]Da-da-da down yeah-yeah yeah-yeah yeah\n[02:46.43]I\'ma take it down oh\n[02:48.80]Da-da-da down ooh\n[02:49.87]It\'s a takedown oh\n[02:51.51]Da-da-da down\n[02:51.99]Watch me do it yeah\n[02:53.73]Take it down', -1, 98, '歌词中存在多处明确暴力、血腥及极端行为描写，包括：\'I\'ma cut you open lose control then rip out your heart\'（我要剖开你，失控后撕出你的心脏）、\'영혼 없는 네 목숨을 끊으러\'（为斩断你这无灵魂的生命而来）、\'정신을 놓고 널 짓밟고 칼을 새겨놔\'（让你失去意识，将你踩在脚下，用刀刻下印记）、\'And watch you die\'（看着你死去）等。这些表述超出隐喻或虚构叙事的合理边界，构成具象化、主动施加的致命暴力行为描述，符合‘极端行为、血腥描写’及‘宣扬暴力’审核标准。虽歌曲设定于虚构电影《kpop猎魔女团》，但歌词未作足够艺术距离化处理，暴力意象密集、直白、重复强化（如多次‘takedown’与‘down’拟声化模拟击倒/摧毁），易产生煽动性暗示。歌词中存在多处暴力、血腥及恶意贬损性表达，严重违反低俗与不良价值观引导审核标准：1）\'I\'ma cut you open lose control then rip out your heart\'（我要剖开你，失控后撕出你的心脏）——具象化暴力伤害行为，渲染极端血腥场景；2）\'Break you into pieces in a world of pain\'（把你撕成碎片，在痛苦的世界里）——宣扬肢体毁灭与施虐倾向；3）\'영혼 없는 네 목숨을 끊으러\'（为斩断你这无灵魂的生命而来）、\'And watch you die\'（看着你死去）——直接涉及致死威胁与死亡暗示；4）反复将他人污名化为\'demon with no feelings\'（没有感情的恶魔）、\'rotten within\'（内在腐烂）、\'ugly as sin\'（丑陋如罪），构成人格侮辱与恶意妖魔化；5）整体语境鼓吹以暴制暴、非理性仇恨宣泄，违背健康向上的价值观引导要求。虽有虚构设定背景（猎魔女团），但暴力描写超出艺术隐喻范畴，具备现实危害诱导风险。歌词中存在大量反人类、煽动仇恨与暴力的极端表述，严重违背社会核心价值观：1）反复出现\'kill you\'、\'cut you open\'、\'rip out your heart\'、\'watch you die\'等直接暴力致死意象；2）将他人污名化为\'demon with no feelings\'、\'rotten within\'、\'ugly as sin\'，构成人格贬损与非人化描述；3）使用\'break you into pieces in a world of pain\'、\'beggin\' and cryin\' all of you dyin\'\'等施虐性语言，宣扬以痛苦为乐的反社会快感；4）韩语部分\'정신을 놓고 널 짓밟고 칼을 새겨놔\'（放开理智践踏你，用刀刻下印记）、\'영혼 없는 네 목숨을 끊으러\'（为斩断你这无魂之命而来）明确表达剥夺生命意图；5）全曲以\'Takedown\'为核心口号，将暴力征服美化为正义行动，缺乏基本人性反思与法律边界意识。整体符合反人类言论与煽动极端暴力行为的审核标准。', '{\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":null},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"FAIL\",\"confidence\":98,\"reason\":\"歌词中存在多处明确暴力、血腥及极端行为描写，包括：\'I\'ma cut you open lose control then rip out your heart\'（我要剖开你，失控后撕出你的心脏）、\'영혼 없는 네 목숨을 끊으러\'（为斩断你这无灵魂的生命而来）、\'정신을 놓고 널 짓밟고 칼을 새겨놔\'（让你失去意识，将你踩在脚下，用刀刻下印记）、\'And watch you die\'（看着你死去）等。这些表述超出隐喻或虚构叙事的合理边界，构成具象化、主动施加的致命暴力行为描述，符合‘极端行为、血腥描写’及‘宣扬暴力’审核标准。虽歌曲设定于虚构电影《kpop猎魔女团》，但歌词未作足够艺术距离化处理，暴力意象密集、直白、重复强化（如多次‘takedown’与‘down’拟声化模拟击倒/摧毁），易产生煽动性暗示。\"},{\"agentName\":\"ExplicitContent\",\"verdict\":\"FAIL\",\"confidence\":98,\"reason\":\"歌词中存在多处暴力、血腥及恶意贬损性表达，严重违反低俗与不良价值观引导审核标准：1）\'I\'ma cut you open lose control then rip out your heart\'（我要剖开你，失控后撕出你的心脏）——具象化暴力伤害行为，渲染极端血腥场景；2）\'Break you into pieces in a world of pain\'（把你撕成碎片，在痛苦的世界里）——宣扬肢体毁灭与施虐倾向；3）\'영혼 없는 네 목숨을 끊으러\'（为斩断你这无灵魂的生命而来）、\'And watch you die\'（看着你死去）——直接涉及致死威胁与死亡暗示；4）反复将他人污名化为\'demon with no feelings\'（没有感情的恶魔）、\'rotten within\'（内在腐烂）、\'ugly as sin\'（丑陋如罪），构成人格侮辱与恶意妖魔化；5）整体语境鼓吹以暴制暴、非理性仇恨宣泄，违背健康向上的价值观引导要求。虽有虚构设定背景（猎魔女团），但暴力描写超出艺术隐喻范畴，具备现实危害诱导风险。\"},{\"agentName\":\"AntiSocial\",\"verdict\":\"FAIL\",\"confidence\":98,\"reason\":\"歌词中存在大量反人类、煽动仇恨与暴力的极端表述，严重违背社会核心价值观：1）反复出现\'kill you\'、\'cut you open\'、\'rip out your heart\'、\'watch you die\'等直接暴力致死意象；2）将他人污名化为\'demon with no feelings\'、\'rotten within\'、\'ugly as sin\'，构成人格贬损与非人化描述；3）使用\'break you into pieces in a world of pain\'、\'beggin\' and cryin\' all of you dyin\'\'等施虐性语言，宣扬以痛苦为乐的反社会快感；4）韩语部分\'정신을 놓고 널 짓밟고 칼을 새겨놔\'（放开理智践踏你，用刀刻下印记）、\'영혼 없는 네 목숨을 끊으러\'（为斩断你这无魂之命而来）明确表达剥夺生命意图；5）全曲以\'Takedown\'为核心口号，将暴力征服美化为正义行动，缺乏基本人性反思与法律边界意识。整体符合反人类言论与煽动极端暴力行为的审核标准。\"}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"FAIL\",\"confidence\":98,\"failReasons\":\"歌词中存在多处明确暴力、血腥及极端行为描写，包括：\'I\'ma cut you open lose control then rip out your heart\'（我要剖开你，失控后撕出你的心脏）、\'영혼 없는 네 목숨을 끊으러\'（为斩断你这无灵魂的生命而来）、\'정신을 놓고 널 짓밟고 칼을 새겨놔\'（让你失去意识，将你踩在脚下，用刀刻下印记）、\'And watch you die\'（看着你死去）等。这些表述超出隐喻或虚构叙事的合理边界，构成具象化、主动施加的致命暴力行为描述，符合‘极端行为、血腥描写’及‘宣扬暴力’审核标准。虽歌曲设定于虚构电影《kpop猎魔女团》，但歌词未作足够艺术距离化处理，暴力意象密集、直白、重复强化（如多次‘takedown’与‘down’拟声化模拟击倒/摧毁），易产生煽动性暗示。歌词中存在多处暴力、血腥及恶意贬损性表达，严重违反低俗与不良价值观引导审核标准：1）\'I\'ma cut you open lose control then rip out your heart\'（我要剖开你，失控后撕出你的心脏）——具象化暴力伤害行为，渲染极端血腥场景；2）\'Break you into pieces in a world of pain\'（把你撕成碎片，在痛苦的世界里）——宣扬肢体毁灭与施虐倾向；3）\'영혼 없는 네 목숨을 끊으러\'（为斩断你这无灵魂的生命而来）、\'And watch you die\'（看着你死去）——直接涉及致死威胁与死亡暗示；4）反复将他人污名化为\'demon with no feelings\'（没有感情的恶魔）、\'rotten within\'（内在腐烂）、\'ugly as sin\'（丑陋如罪），构成人格侮辱与恶意妖魔化；5）整体语境鼓吹以暴制暴、非理性仇恨宣泄，违背健康向上的价值观引导要求。虽有虚构设定背景（猎魔女团），但暴力描写超出艺术隐喻范畴，具备现实危害诱导风险。歌词中存在大量反人类、煽动仇恨与暴力的极端表述，严重违背社会核心价值观：1）反复出现\'kill you\'、\'cut you open\'、\'rip out your heart\'、\'watch you die\'等直接暴力致死意象；2）将他人污名化为\'demon with no feelings\'、\'rotten within\'、\'ugly as sin\'，构成人格贬损与非人化描述；3）使用\'break you into pieces in a world of pain\'、\'beggin\' and cryin\' all of you dyin\'\'等施虐性语言，宣扬以痛苦为乐的反社会快感；4）韩语部分\'정신을 놓고 널 짓밟고 칼을 새겨놔\'（放开理智践踏你，用刀刻