INSERT INTO `track_review_records` VALUES (2071964518675521538, 2071964514275696642, 'ETA', 'New Jeans', 'New Jeans Album', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'ETA\' 为英文缩写，常见含义包括 \'Estimated Time of Arrival\'（预计到达时间），亦可能指代其他中性或技术性概念；在无歌词、无上下文语境的情况下，无法确认其指向任何政治实体、组织或敏感事件。\'ETA\' 虽曾被用作西班牙分离主义组织 \'Euskadi Ta Askatasuna\'（巴斯克祖国与自由）的缩写，但该组织属外国历史政治团体，与中国主权、政权、领土、领导人及重大政治事件无关联；且标题未附带任何说明性文字、符号、旗帜、地图等强化敏感指向的元信息。歌手 \'New Jeans\' 为韩国流行音乐组合，专辑名 \'New Jeans Album\' 为常规商业命名，无政治暗示。根据审核原则：\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'；且标题 \'ETA\' 不构成对中国的反国家、颠覆政权、领土主权否定、领导人侮辱或敏感事件不当评论的直接或明确表达，亦无证据表明其在此语境下被赋予上述敏感含义。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"标题\'ETA\'为常见中性缩写，无歌词佐证其恐怖主义指向，不符合任一命中标准\",\"analysis\":\"仅提供元信息：歌曲标题为\'ETA\'，歌手为New Jeans，专辑名为\'New Jeans Album\'。\'ETA\'是常见缩写，可能指\'Estimated Time of Arrival\'（预计到达时间），亦可能被联想为西班牙分离主义组织\'Euskadi Ta Askatasuna\'（巴斯克祖国与自由）的缩写。但无歌词、无上下文说明、无视觉元素（如封面、宣传物料）佐证其指向恐怖组织；歌手New Jeans为韩国流行音乐团体，一贯风格为青春、清新、都市感，无已知涉恐关联；专辑名及艺人信息均无恐怖组织标识、口号或宣传语。根据审核原则\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，且\'ETA\'属多义缩写，无直接、明确证据表明其宣扬暴力、恐怖主义，或展示恐怖组织相关内容。因此，四条标准均未命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法支持任何色情低俗判定，符合\'无歌词时confidence不超过60\'要求\",\"analysis\":\"歌曲标题 \'ETA\' 是英文缩写，常见含义为 \'Estimated Time of Arrival\'（预计到达时间），属中性、通用术语；歌手名 \'New Jeans\' 指代牛仔裤品牌或青春意象，无色情低俗指向；专辑名 \'New Jeans Album\' 与歌手名一致，属常规命名逻辑。四条审核标准均需基于具体内容（如露骨性描写、侮辱性词汇、违法鼓