INSERT INTO `track_review_records` VALUES (2071965177877504001, 2071965172668178433, 'Attention', 'New Jeans', 'New Jeans Album', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"元信息无政治敏感内容，但因无歌词，判断依据有限，置信度按规则上限设为60\",\"analysis\":\"歌曲标题 \'Attention\' 为英文常见词汇，意为\'注意\'或\'关注\'，无政治语义；歌手名 \'New Jeans\' 为韩国流行音乐团体名称，属品牌化艺名，与政治无关；专辑名 \'New Jeans Album\' 为常规专辑命名方式。所有元信息中未出现任何涉及国家政权、领土主权、政治领导人或敏感事件的表述，亦无暗示性用语。根据审核原则，仅凭标题/艺人名等元信息且无歌词时，无法构成对任一审核标准的明确命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法支持任何暴力恐怖维度的判定，符合\'无歌词时confidence不超过60\'的要求\",\"analysis\":\"歌曲标题\'Attention\'为常见英文词汇，意为\'注意、关注\'，无暴力、恐怖主义、极端行为、血腥、煽动冲突或恐怖组织相关语义；歌手名\'New Jeans\'为时尚品牌名衍生的艺人名称，属中性商业命名；专辑名\'New Jeans Album\'亦无敏感指向。根据审核原则，仅凭元信息（无歌词）无法构成对任一审核标准的明确命中证据，且标题与歌手/专辑名均未出现\'血\'\'杀\'\'炸\'\'恐\'\'袭\'等敏感字眼，更无恐怖组织标识、口号或宣传语。因此，四条标准均未命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"标题及元信息无色情、侮辱、违法引导或庸俗化表达，符合豁免情形；因无歌词，判断依据有限，置信度按规则上限设为60\",\"analysis\":\"仅提供元信息：歌曲标题为\'Attention\'，歌手为\'New Jeans\'，专辑名为\'New Jeans Album\'。标题\'Attention\'为英文常见词汇，意为\'注意、关注\'，无固有色情、低俗、侮辱或违法含义；歌手名\'New Jeans\'指代牛仔裤，属时尚/青春意象，常见于K-pop语境，不构成性暗示或庸俗化表达；专辑名同理，为常规命名方式。无歌词内容，无法判断是否存在隐喻、反讽或语境化表达。根据审核原则：\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'；且\'歌名含敏感字眼但语境正常（如历史题材、情感隐喻）不应直接判 FAIL\'——而\'Attention\'本身并非敏感字眼，亦无双关、谐音或文化语境中公认的低俗指向（如无\'cum\',\'dick\'等明确敏感词），故四条标准均无命中证据。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Attention\' 为常见英文词汇，意为\'注意、关注\'，无明确反社会、反人类含义；歌手名 \'New Jeans\' 为时尚品牌化艺名，属中性商业命名；专辑名 \'New Jeans Album\' 同样无敏感指向。根据审核原则，\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'；所有审核标准均要求存在明确表达（如言论、煽动、宣扬、鼓吹），而当前元信息中无任何涉及反社会、仇恨煽动、极端思想或违法破坏的文本证据；标题\'Attention\'在音乐语境中普遍用于表达情感诉求或吸引聆听，属常规艺术命名，不构成对任何群体的歧视或价值否定，亦不暗示极端意识形态或违法行为。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"四个维度（PoliticalSensitivity、ViolenceTerror、ExplicitContent、AntiSocial）均判定为PASS，confidence均为60，原因一致：仅含元信息（标题\'Attention\'、艺人\'New Jeans\'、专辑名），无歌词，无法支撑任何敏感内容的实质性判断；各analysis均严谨指出标题为中性英文常用词，艺人及专辑名为商业/时尚化命名，无政治、暴力、色情或反社会语义，且未依赖隐喻联想或过度解读——例如未将\'Attention\'强行关联\'attention economy\'批判或\'attention-seeking\'病理化等延伸解读，亦未对\'Jeans\'作不当性暗示推演。因此，不存在需触发\'过度敏感纠偏\'的情形；所有维度结论合理、一致、证据充分，且无PENDING项。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2071965177877504001,\"trackId\":2071965172668178433,\"trackTitle\":\"Attention\",\"startedAt\":\"2026-06-30T22:32:48.673209900\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":3,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"元信息无政治敏感内容，但因无歌词，判断依据有限，置信度按规则上限设为60\",\"startedAt\":null,\"finishedAt\":\"2026-06-30T22:32:53.364780300\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法支持任何暴力恐怖维度的判定，符合\'无歌词时confidence不超过60\'的要求\",\"startedAt\":\"2026-06-30T22:32:49.335335100\",\"finishedAt\":\"2026-06-30T22:32:53.588868400\",\"durationMs\":4253},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"标题及元信息无色情、侮辱、违法引导或庸俗化表达，符合豁免情形；因无歌词，判断依据有限，置信度按规则上限设为60\",\"startedAt\":\"2026-06-30T22:32