INSERT INTO `track_review_records` VALUES (2071965353211994114, 2071965348296269826, 'Super Shy', 'New Jeans', 'New Jeans Album', NULL, -2, 50, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":50},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Super Shy\'、歌手 \'New Jeans\'、专辑名 \'New Jeans Album\' 均为英文命名，属常见流行音乐命名风格，无中文政治敏感字词；\'Super Shy\' 为描述性格状态的日常用语（极度害羞），不涉及任何政治实体、制度、领土、领导人或历史事件；\'New Jeans\' 是韩国女子音乐组合名称，源自时尚意象，无歧义性政治指涉；专辑名亦为常规商业命名。所有元信息均未出现反国家、颠覆政权、领土主权错误表述、领导人侮辱或政治敏感事件评论等任何直接或明确暗示性内容；根据审核原则，无歌词时仅凭标题/署名判断，且题目无敏感语义，属中性娱乐表达。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题\'Super Shy\'、歌手\'New Jeans\'、专辑名\'New Jeans Album\'均不含任何暴力、恐怖主义、极端行为、血腥描写、煽动暴力冲突或恐怖组织相关字眼或暗示；\'Shy\'为常见英文情感形容词，表羞涩、腼腆，属中性/积极情绪表达；无歌词内容可供分析，仅凭元信息无法关联任何审核标准中的命中情形；根据审核原则，\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，且所有标准项均无证据支持命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":50,\"reason\":\"仅凭标题\'Super Shy\'无法构成色情低俗判定，属中性情感表达，但缺乏歌词佐证，置信度受限\",\"analysis\":\"歌曲标题 \'Super Shy\' 为英文常见短语，字面意为\'极度害羞\'，属中性情感描述，无露骨性描写或明显性暗示（未命中标准1）；无任何针对群体的谩骂或人格侮辱性词汇（未命中标准2）；未出现违法、吸毒、嫖娼等行为相关表述，亦无鼓吹倾向（未命中标准3）；\'Super Shy\' 是简洁、生活化的心理状态表达，符合青少年流行文化语境，非以低俗博眼球或粗鄙表达，属正常艺术命名范畴（未命中标准4）。因歌词缺失，仅凭标题审核，且\'Shy\'在英语中无色情低俗固定引申义，\'Super\'为程度强化词，整体无双关、谐音或隐晦低俗指向，属常规情感形容，证据薄弱。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Super Shy\' 为常见英语口语表达，意指‘极度害羞’，属中性情感描述；歌手名 \'New Jeans\' 为时尚化艺名，无政治、宗教或意识形态指向；专辑名 \'New Jeans Album\' 为常规命名方式。所有元