INSERT INTO `track_review_records` VALUES (2071965761779146754, 2071965754518806530, 'Bubble Gum', 'New Jeans', 'New Jeans Album', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题\'Bubble Gum\'为常见英文词汇，指口香糖，属日常消费品名称，无政治含义；歌手名\'New Jeans\'为时尚服饰品类，属中性商业命名；专辑名\'New Jeans Album\'为常规专辑命名方式。三者均未出现任何中文敏感字词，亦无涉及国家政权、领土主权、领导人、重大政治事件的直接或暗示性表述。根据审核原则，仅凭元信息且无歌词时，confidence 不超过 60；所有四条审核标准均无对应证据支持命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题\'Bubble Gum\'为常见糖果名称，无暴力、恐怖主义、极端行为、血腥、煽动冲突或恐怖组织相关语义；歌手\'New Jeans\'为韩国流行音乐团体名称，属常规艺名；专辑名\'New Jeans Album\'为标准专辑命名方式。所有元信息均未出现敏感字眼（如血、杀、炸、恐、暴等），亦无任何暗示暴力恐怖的符号、缩写或隐喻。根据审核原则，无歌词时仅凭标题等元信息判断，且confidence不超过60；此处元信息完全中性，无任何命中证据。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"仅审核元信息（歌名 \'Bubble Gum\'、歌手 \'New Jeans\'、专辑名 \'New Jeans Album\'），无歌词可供分析。\'Bubble Gum\' 为常见英文词汇，指泡泡糖，常用于形容轻快、甜美、青春风格的音乐或形象，在流行文化中属中性甚至积极意象；无露骨性描写或明显性暗示，不构成色情低俗内容（未命中标准1）；无任何侮辱性词汇或指向特定群体的贬损表达（未命中标准2）；无鼓吹违法、吸毒、嫖娼等行为的语义（未命中标准3）；\'Bubble Gum\' 作为音乐风格/气质隐喻（如甜腻、弹性、少女感），属常规艺术化命名，非以低俗博眼球或粗鄙表达（未命中标准4）。根据审核原则，仅凭标题含常见英文词且无不良语境，不应直接判FAIL；且明确提示\'无歌词，仅审核元信息\'，confidence 不超过60。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Bubble Gum\' 为常见英文词汇，指代一种糖果，常用于形容轻快、甜美、青春风格的流行文化意象；歌手名 \'New Jeans\' 是韩国流行音乐团体名称，源自牛仔裤（jeans）的时尚符号，属中性商业命名；专辑名 \'New Jeans Album\' 为常规专辑命名方式。所有元信息均无涉反社会、反人类言论（标准1），未出现任何针对种族/民族/宗教/性别的贬损或仇恨性表述（标准2），未包含极端主义意识形态关键词或符号（标准3），亦无鼓吹违法犯罪或破坏公共秩序的语义（标准4）。根据审核原则，\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，且所有元信息均属日常、中性、无敏感语境的商业命名，不构成任何标准的命中依据。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"四个维度（PoliticalSensitivity、ViolenceTerror、ExplicitContent、AntiSocial）均判定为 PASS，confidence 均为 60，且各自 analysis 均逻辑清晰、证据充分：标题 \'Bubble Gum\' 属日常消费品词汇，在全球流行文化中广泛用于形容青春、甜美、轻盈的音乐风格（如 bubblegum pop），无任何政治、暴力、色情或反社会语义；歌手名 \'New Jeans\' 与专辑名均为常规时尚化艺名与命名惯例，无歧义、无隐喻敏感性。所有维度均明确指出‘无歌词’，故仅基于元信息审核，confidence 统一上限为 60 符合规则，不存在过度敏感问题——未出现任何维度依赖隐喻联想、艺术过敏或歌名误读等需纠偏的情形；亦无任一维度报 FAIL 或 PENDING，不触发一票否决、多维共振或人工转交机制。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2071965761779146754,\"trackId\":2071965754518806530,\"trackTitle\":\"Bubble Gum\",\"startedAt\":\"2026-06-30T22:35:07.943452800\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":3,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":null,\"finishedAt\":\"2026-06-30T22:35:11.994079200\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"RUNNING\",\"verdict\":null,\"confidence\":null,\"reason\":null,\"startedAt\":\"2026-06-30T22:35:08.188107400\",\"finishedAt\":null,\"durationMs\":null},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T22:35:09.436015900\",\"finishedAt\":\"2026-06-30T22:35:14.110305700\",\"durationMs\":4674},{\"agentName\":\"AntiSocial\",\"displayName\":\"反社会\",\"order\":40,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T22:35:12.311258400\",\"finishedAt\":\"2026-06-30T22:35:16.964738200\",\"durationMs\":4653}],\"judge\":{\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T22:35:17.286922600\",\"finishedAt\":\"2026-06-30T22:35:23.226959300\",\"durationMs\":5940},\"finishedAt\":\"2026-06-30T22:35:23.623749800\",\"finalStatus\":3,\"finalVerdict\":-2,\"finalConfidence\":60}', 4, 1, 1, NULL, '2026-06-30 22:41:38', '2026-06-30 22:35:07', '2026-06-30 22:35:23');
INSERT INTO `track_review_records` VALUES (2071965889671864321, 2071965884630310913, 'Get Up', 'New Jeans', 'New Jeans Album', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Get Up\' 为常见英文短语，意为起身、振作、行动等，属中性积极表达；歌手名 \'New Jeans\' 为韩国流行音乐组合名称，无政治含义；专辑名 \'New Jeans Album\' 为常规专辑命名方式。所有元信息均未出现反国家、颠覆政权、领土主权错误表述、领导人侮辱性用语或对政治敏感事件的不当评论。根据审核原则，仅凭标题/艺人名等元信息且无歌词支撑时，无法构成对任一审核标准的明确命中；\'Get Up\' 在艺术语境中常见于励志、觉醒等主题，属豁免范畴（艺术表达）。因此四条标准均未命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法支持任何暴力恐怖维度的判定，符合‘无歌词时confidence不超过60’的要求，且标题语义中性偏积极，未触发任一审核标准。\",\"analysis\":\"歌曲标题 \'Get Up\' 为常见英文短语，含义为起身、振作、活跃等，无暴力、恐怖主义、极端行为、血腥描写或恐怖组织相关暗示；歌手名 \'New Jeans\' 为时尚品牌名称衍生的艺名，与暴力恐怖无关；专辑名 \'New Jeans Album\' 同样无敏感指向。根据审核原则，仅凭元信息（无歌词）无法确认任何暴力恐怖维度的直接表达或明确暗示；标题 \'Get Up\' 在音乐语境中普遍用于积极主题（如励志、舞曲唤醒感），不构成标准1)-4)中的任一命中情形。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法确认违规，\'Get Up\'属中性多义短语，符合置信度上限60要求\",\"analysis\":\"歌曲标题 \'Get Up\' 为常见英文短语，含义包括\'起床\'\'振作起来\'\'起身\'等，属中性日常表达；歌手名 \'New Jeans\' 指牛仔裤品牌或青春意象，无色情低俗指向；专辑名 \'New Jeans Album\' 与歌手名一致，属常规命名逻辑。四条审核标准均需基于具体内容（如歌词）或明确语境判断：1) 无歌词，无法确认是否存在露骨性描写或性暗示；\'Get Up\' 单独存在时属多义中性词，常见于健身、励志、舞曲等非低俗场景，不构成明显性暗示；2) 标题及署名中无侮辱性词汇，未指向任何群体；3) 无内容体现违法/吸毒/嫖娼等行为引导；4) \'Get Up\' 非粗鄙表达，亦非以低俗博眼球的庸俗化用语。综上，所有标准均无命中证据。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法判定违规，且标题无负面语义，符合豁免情形\",\"analysis\":\"歌曲标题 \'Get Up\' 为常见英文短语，含义为\'起身、振作、行动起来\'，属中性积极表达，无反社会、反人类内涵；歌手名 \'New Jeans\' 为时尚品牌名称衍生的艺名，无意识形态指向；专辑名 \'New Jeans Album\' 同样无敏感语义。根据审核原则，仅凭元信息（无歌词）无法确认存在反社会、反人类言论（标准1）、仇恨煽动（标准2）、极端思想传播（标准3）或违背核心价值观的鼓吹（标准4）。所有标准均缺乏直接证据支持，且标题语境属常规激励性用语，符合主流价值导向。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"四个维度均判为PASS，confidence均为60，且各自analysis逻辑一致、充分：所有agent均指出\'Get Up\'为中性积极英文短语，无政治、暴力恐怖、色情低俗或反社会含义；歌手名\'New Jeans\'和专辑名均为常规商业/艺术命名，无隐喻歧义或敏感联想；关键共性在于——无歌词支撑，仅凭元信息无法触发任一维度的实质性违规判定，且各分析均主动援引‘艺术表达豁免’‘中性多义不构成暗示’‘无证据不推定’等合规原则，未出现过度敏感问题（如未将\'Get Up\'强行解读为政治动员或暴力指令）。不存在一票否决项（无FAIL），无PENDING项，亦无≥2个FAIL维度。四维全PASS，符合‘全PASS’裁决规则。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2071965889671864321,\"trackId\":2071965884630310913,\"trackTitle\":\"Get Up\",\"startedAt\":\"2026-06-30T22:35:38.418764800\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":3,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":null,\"finishedAt\":\"2026-06-30T22:35:42.432584800\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"RUNNING\",\"verdict\":null,\"confidence\":null,\"reason\":null,\"startedAt\":\"2026-06-30T22:35:38.670385200\",\"finishedAt\":null,\"durationMs\":null},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法确认违规，\'Get Up\'属中性多义短语，符合置信度上限60要求\",\"startedAt\":\"2026-06-30T22:35:42.677716700\",\"finishedAt\":\"2026-06-30T22:35:47.912560700\",\"durationMs\":5234},{\"agentName\":\"AntiSocial\",\"displayName\":\"反社会\",\"order\":40,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法判定违规，且标题无负面语义，符合豁免情形\",\"startedAt\":\"2026-06-30T22:35:42.877468800\",\"finishedAt\":\"2026-06-30T22:35:46.703631600\",\"durationMs\":3826}],\"judge\":{\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T22:35:48.153890\",\"finishedAt\":\"2026-06-30T22:35:52.286452100\",\"durationMs\":4132},\"finishedAt\":\"2026-06-30T22:35:52.639219400\",\"finalStatus\":3,\"finalVerdict\":-2,\"finalConfidence\":60}', 4, 1, 1, NULL, '2026-06-30 22:41:31', '2026-06-30 22:35:37', '2026-06-30 22:35:52');
INSERT INTO `track_review_records` VALUES (2071966439960354818, 2071966435828965377, 'Kill This Love', 'Black Pink', 'Kill This Love', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅审核元信息，标题为常规情感隐喻，无政治指向性证据\",\"analysis\":\"歌曲标题\'Kill This Love\'及专辑名均为英文短语，字面意为\'终结这段爱情\'，属常见情感类流行音乐命名惯例；\'Kill\'在此为俚语化修辞，表示强烈决断或情感断裂，不涉及暴力政治含义；\'This Love\'指代具体人际关系，无任何国家、政权、领土、领导人或政治事件指向；歌手Black Pink为韩国流行音乐团体，其作品一贯聚焦青春、女性意识、情感主题，无政治表达意图；元信息中无歌词、无中文语境、无历史/政治专有名词，亦无地图、疆域、宪法、领导人姓名等敏感要素；根据审核原则，仅凭标题含\'Kill\'一词不能推定政治颠覆意图，该词在音乐工业中高频用于非政治语境（如\'Kill Me\'、\'Kill Em All\'等均属艺术表达豁免范畴）；无证据表明其暗示反国家、主权错误、侮辱领导人或不当评论政治事件。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭标题\'Kill This Love\'无法确认暴力或恐怖主义意图，属常见情感隐喻，符合豁免情形\",\"analysis\":\"仅提供元信息：标题\'Kill This Love\'、歌手BLACKPINK、专辑名同标题。\'Kill\'为英语常见动词，在流行音乐中广泛用于情感隐喻（如\'kill the mood\'、\'kill it\'表表现极佳），此处\'Kill This Love\'属典型情感修辞，意指终结一段感情，符合K-pop常见主题；无歌词内容，无法确认语境是否含暴力宣扬或极端描写；标题不含恐怖组织标识、口号或宣传语；未出现战争、恐怖袭击、血腥过程等直接描述；根据审核原则，歌名含敏感字眼但属情感隐喻，且无其他证据支持暴力/恐怖指向，不满足任一命中标准。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭标题无法确认色情低俗意图，属常见情感隐喻表达，符合豁免情形\",\"analysis\":\"仅审核元信息（标题\'Kill This Love\'、歌手\'Black Pink\'、专辑名\'Kill This Love\'），无歌词内容。\'Kill This Love\'为常见英语习语式表达，字面直译虽含\'kill\'，但实际语境中属情感隐喻（意指终结一段失败恋情），广泛用于流行音乐标题（如Avril Lavigne《I\'m with You》、Taylor Swift《We Are Never Ever Getting Back Together》等同类情感决断主题），不构成露骨性描写或明显性暗示，未命中标准1)；标题中无针对任何群体的贬义词汇或侮辱性表述，未命中标准2)；\'Kill This Love\'表达的是对不良关系的主动抽离，属健康情感态度，非鼓吹违法、吸毒、嫖娼等行为，未命中标准3)；该标题具有修辞张力与流行文化惯例支撑，属艺术化浓缩表达，并非以低俗博眼球或粗鄙无内涵的庸俗化表达，未命中标准4)。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭标题\'Kill This Love\'无法确认反社会、反人类、煽动仇恨、极端思想或违背核心价值观意图；属常见情感隐喻，符合豁免情形；confidence 受限于无歌词，按规则上限设为60\",\"analysis\":\"仅提供元信息：歌曲标题\'Kill This Love\'、歌手Black Pink、专辑名\'Kill This Love\'。\'Kill\'为英文动词，在流行音乐语境中常见于比喻性表达（如终结一段感情、告别旧我），属情感隐喻范畴；\'Love\'为中性抽象概念，无特定指涉对象。标题整体符合K-pop常见修辞风格（夸张、戏剧化、情感张力），无明确指向反人类行为、仇恨煽动、极端意识形态或违法犯罪的直接表述。根据审核原则，歌名含敏感字眼但语境正常（情感隐喻），且无歌词佐证其真实意图，不得仅凭字面直译\'杀死爱情\'推定反社会含义；同时，\'Kill\'在此非医学/法律意义的暴力指令，亦未绑定任何种族、民族、宗教、性别等歧视性客体，不构成煽动仇恨；亦无证据表明其传播极端主义意识形态或鼓吹破坏公共秩序。综上，四条标准均无命中证据。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"四个维度均判为PASS，confidence均为60。PoliticalSensitivity维度指出\'Kill\'为俚语化修辞，属常见情感隐喻，无政治指向性证据；ViolenceTerror维度强调无歌词支撑，\'Kill This Love\'在K-pop语境中属典型决断式情感表达，不构成暴力/恐怖意图；ExplicitContent维度确认标题无露骨性暗示、无贬义侮辱、无违法鼓吹，符合艺术化浓缩表达惯例；AntiSocial维度明确指出无仇恨煽动、无歧视客体、无极端意识形态绑定，且confidence受限于无歌词而合理设为60。四者分析逻辑一致、互为印证，均基于元信息审慎排除风险，未出现任何过度敏感误判（如未将\'Kill\'字面化解读为真实暴力指令，亦未因歌名张力误定反社会倾向），无需进行过度敏感纠偏；所有FAIL条件均未触发（无一票否决项，无PENDING，无≥2个FAIL维度），符合全PASS情形。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2071966439960354818,\"trackId\":2071966435828965377,\"trackTitle\":\"Kill This Love\",\"startedAt\":\"2026-06-30T22:37:49.542059100\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":3,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅审核元信息，标题为常规情感隐喻，无政治指向性证据\",\"startedAt\":null,\"finishedAt\":\"2026-06-30T22:37:56.879869400\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭标题\'Kill This Love\'无法确认暴力或恐怖主义意图，属常见情感隐喻，符合豁免情形\",\"startedAt\":\"2026-06-30T22:37:49.992104500\",\"finishedAt\":\"2026-06-30T22:37:54.372693900\",\"durationMs\":4380},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"RUNNING\",\"verdict\":null,\"confidence\":null,\"reason\":null,\"startedAt\":\"2026-06-30T22:37:51.714221700\",\"finishedAt\":null,\"durationMs\":null},{\"agentName\":\"AntiSocial\",\"displayName\":\"反社会\",\"order\":40,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭标题\'Kill This Love\'无法确认反社会、反人类、煽动仇恨、极端思想或违背核心价值观意图；属常见情感隐喻，符合豁免情形；confidence 受限于无歌词，按规则上限设为60\",\"startedAt\":\"2026-06-30T22:37:54.578706700\",\"finishedAt\":\"2026-06-30T22:37:59.909214400\",\"durationMs\":5330}],\"judge\":{\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T22:38:00.235379700\",\"finishedAt\":\"2026-06-30T22:38:06.635912200\",\"durationMs\":6400},\"finishedAt\":\"2026-06-30T22:38:06.956450\",\"finalStatus\":3,\"finalVerdict\":-2,\"finalConfidence\":60}', 4, 1, 1, NULL, '2026-06-30 22:41:04', '2026-06-30 22:37:48', '2026-06-30 22:38:06');
INSERT INTO `track_review_records` VALUES (2071966629857468417, 2071966624379707393, 'How You Like That', 'Black Pink', 'Kill This Love', NULL, -2, 55, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":55},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'How You Like That\'、歌手 \'Black Pink\'、专辑名 \'Kill This Love\' 均为英文流行音乐常见表达，属艺术化、情绪化命名，无任何中文政治语境下的敏感字词；标题与专辑名均不涉及国家政权、领土主权、政治领导人或重大政治事件；\'Kill This Love\' 是比喻性表达（指终结一段失败恋情），属豁免范畴中的艺术表达；\'How You Like That\' 为口语化挑衅式反问，常见于K-pop风格自信宣言，无政治指向；无歌词提供，无法支撑任何政治敏感性推断；根据审核原则\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，所有四条审核标准均无命中证据。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":55,\"reason\":\"仅凭专辑名含\'Kill\'一词，属常见情感隐喻，无其他敏感要素，证据不足，置信度受限于无歌词且元信息模糊\",\"analysis\":\"仅提供元信息：标题 \'How You Like That\'、歌手 \'Black Pink\'、专辑名 \'Kill This Love\'。其中 \'Kill This Love\' 含动词 \'Kill\'，但属常见英语习语式表达（意为‘终结这段感情’），在流行音乐中广泛用于情感隐喻（如告别、决绝），无暴力实施指向；标题与专辑名均未出现恐怖组织名称、标识、口号或任何明确暴力/恐怖主义符号；无歌词内容，无法判断是否存在极端描写或煽动性语句；\'Kill\' 在此语境下不构成血腥描写或现实暴力鼓动，属于艺术化情感修辞，符合豁免情形（艺术隐喻）；亦无证据表明其宣扬恐怖主义、展示恐怖组织相关内容或煽动现实暴力冲突。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"仅提供元信息（标题 \'How You Like That\'、歌手 Black Pink、专辑 \'Kill This Love\'），无歌词内容。标题 \'How You Like That\' 是常见英语口语表达，字面意为‘你觉得那样如何’，在流行音乐中广泛用于表达自信、挑衅或情感反馈，属中性表达；该标题在Blackpink同名歌曲实际歌词语境中指向强势态度与自我宣言，并无露骨性描写或明显性暗示，不满足标准1)；无任何侮辱性词汇或指向特定群体的贬损表述，不满足标准2)；标题未涉及违法、吸毒、嫖娼等行为引导，不满足标准3)；该标题简洁有力，符合K-pop国际化传播惯例，具有艺术张力与品牌辨识度，非为低俗博眼球或粗鄙表达，不满足标准4)。因无歌词，判断完全依赖标题，而‘That’为泛指代词，无独立色情/低俗语义，单独联想‘that’指代性器官属于过度解读，不符合审核原则中‘不做过度隐喻联想’的要求。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'How You Like That\'、歌手 \'Black Pink\'、专辑名 \'Kill This Love\' 均为常见英文表达，无明确反社会、反人类语义：\'How You Like That\' 是口语化挑衅式反问，属流行文化常见自信/强势表达；\'Kill This Love\' 中 \'kill\' 在音乐语境中常为修辞（如 \'kill it\' 表示表现极佳），专辑整体主题聚焦女性力量与情感挣脱，并非鼓吹暴力或否定爱的价值；三者均无针对种族/民族/宗教/性别的仇恨指向；无极端主义意识形态词汇；未出现违法犯罪或破坏公共秩序的直接倡导。因歌词缺失，仅凭元信息无法确认是否存在隐含违规内容，且标题/专辑名在K-pop语境中属常规艺术命名惯例，符合豁免情形（艺术表达、情感隐喻）。根据审核原则\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，证据强度不足。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":55,\"analysis\":\"四个维度均判 PASS，无 FAIL 或 PENDING。PoliticalSensitivity、ExplicitContent、AntiSocial 均以 confidence=60 判 PASS，理由充分：标题与专辑名均为 K-pop 常见艺术化表达，\'Kill This Love\' 属情感隐喻（终结恋情），\'How You Like That\' 是口语化自信宣言，三者均无政治指向、暴力实指、色情暗示或反社会语义；ViolenceTerror 维度 confidence=55（略低），但分析明确指出 \'Kill\' 在此为习语式修辞，无血腥描写、恐怖关联或现实暴力鼓动，符合艺术隐喻豁免情形，且无歌词支撑任何升级推断——该维度虽置信度最低，但仍属有效 PASS。未出现任一维度 FAIL 或 PENDING，故不触发一票否决、多维共振或人工介入规则；所有维度均未发生过度敏感问题（如未将 \'kill\' 字面化误读为暴力指令，亦未对 \'that\' 做性器官联想），无需纠偏。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2071966629857468417,\"trackId\":2071966624379707393,\"trackTitle\":\"How You Like That\",\"startedAt\":\"2026-06-30T22:38:34.881406300\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":4,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":null,\"finishedAt\":\"2026-06-30T22:38:40.808717800\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":55,\"reason\":\"仅凭专辑名含\'Kill\'一词，属常见情感隐喻，无其他敏感要素，证据不足，置信度受限于无歌词且元信息模糊\",\"startedAt\":\"2026-06-30T22:38:35.404536\",\"finishedAt\":\"2026-06-30T22:38:39.899501400\",\"durationMs\":4494},{\