INSERT INTO `track_review_records` VALUES (2071966959559122946, 2071966955821998081, 'Hit You With that Du Du Du', 'Black Pink', 'Kill This Love', NULL, -2, 45, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":45},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Hit You With that Du Du Du\' 为拟声词构成的流行音乐常见风格化表达，无明确政治语义；\'Black Pink\' 为韩国女子音乐组合法定艺名，不涉及政治领导人指代或侮辱；专辑名 \'Kill This Love\' 属情感隐喻范畴，常见于爱情主题流行音乐，无颠覆政权、领土主张或事件评论含义。根据审核原则，仅凭元信息（无歌词）无法确认任何政治敏感内容，且标题与艺人名称均未出现反国家、主权错误、领导人侮辱或敏感事件评论等直接表述。符合\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'的要求。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭标题无法确认暴力恐怖意图，\'Hit\'和\'Kill\'在流行音乐中属常规隐喻用法，符合豁免情形\",\"analysis\":\"仅提供元信息：歌曲标题\'Hit You With that Du Du Du\'、歌手\'Black Pink\'、专辑\'Kill This Love\'，无歌词内容。标题中\'Hit You\'含物理攻击动词，但\'du du du\'为拟声/节奏性重复音节，常见于K-pop舞曲标题（如类似\'Bang Bang Bang\'、\'DDU-DU DDU-DU\'），属艺术化表达，无明确暴力意图；专辑名\'Kill This Love\'中\'Kill\'为英语常见情感隐喻（意为\'终结这段感情\'），在流行音乐中广泛使用（如\'Kill Me Now\'、\'Kill the Lights\'），属豁免范畴（审核原则第3条：艺术表达、情感隐喻）；未出现恐怖组织标识、口号、血腥细节或煽动性指令；无任何元信息指向恐怖主义、极端行为或暴力冲突的直接宣扬。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":45,\"reason\":\"仅凭标题\'Hit You With that Du Du Du\'无法确证色情低俗，属边界联想，置信度受限于无歌词证据\",\"analysis\":\"仅审核元信息（歌名\'Hit You With that Du Du Du\'），无歌词。\'Du Du Du\'为拟声词/节奏性重复，常见于K-pop歌曲标题中（如BTS《Ddu-Du Ddu-Du》），属音乐性表达，非明确性暗示或露骨描写；无侮辱性语言、不良价值观引导内容；该标题虽含重复音节，但属流行音乐常见命名风格，并非以低俗博眼球的粗鄙表达，而是强调律动与记忆点，符合艺术惯例。根据审核原则，歌名含敏感字眼需结合歌词判断，但本例无歌词，故无法确认语境，仅凭标题无法认定为色情低俗或庸俗化表达。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"标题 \'Hit You With that Du Du Du\' 为拟声词构成的流行音乐常见风格化表达，无明确语义指向；\'Du Du Du\' 属无意义音节重复，常见于K-pop舞蹈曲目中用于节奏强调（如类似 \'Boom Boom Pow\'、\'La La La\'），不构成反社会、反人类言论（标准1未命中）；未出现任何种族、民族、宗教、性别相关词汇，无法构成针对特定群体的仇恨或歧视煽动（标准2未命中）；标题不含极端主义意识形态关键词（如\'圣战\'\'净化\'\'终焉\'等），亦无政治/宗教极端符号或隐喻（标准3未命中）；\'Hit You\' 在流行音乐语境中普遍指舞台表现力强、节奏冲击力大，属行业惯用修辞（如 \'hit the stage\', \'hit the beat\'），不具真实暴力鼓动性，未鼓吹违法犯罪或破坏公共秩序（标准4未命中）。根据审核原则，仅凭标题且无歌词时，confidence 不超过 60；该标题在K-pop语境中属常规娱乐化命名，无异常语义负荷。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":45,\"analysis\":\"四个维度均判为PASS：PoliticalSensitivity（confidence=60）指出标题为拟声风格化表达，无政治语义，且明确援引审核原则‘无歌词时confidence不超过60’，结论合理；ViolenceTerror（confidence=60）正确识别‘Hit’‘Kill’在K-pop语境中属情感隐喻与艺术豁免范畴，分析紧扣‘无歌词+常见修辞’双重依据，未过度解读；ExplicitContent（confidence=45）虽置信度最低，但理由充分——‘Du Du Du’确为典型K-pop拟声命名惯例（如BTS《DDU-DU DDU-DU》），无实指性含义，且明确说明‘无歌词无法确认语境’，符合审慎原则，未因音节重复作边界联想误判；AntiSocial（confidence=60）全面覆盖四类反社会标准，指出‘Hit You’在舞台语境中指表现力而非真实攻击，并关联行业惯用语（hit the stage），分析扎实。四维度均无FAIL，亦无PENDING；不存在一票否决情形；无任一维度出现过度敏感问题（如将拟声词‘Du Du Du’误读为低俗暗示或暴力指令），故无需权重下调；全部PASS，整体confidence取最低值45。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2071966959559122946,\"trackId\":2071966955821998081,\"trackTitle\":\"Hit You With that Du Du Du\",\"startedAt\":\"2026-06-30T22:39:53.419859100\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":4,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":null,\"finishedAt\":\"2026-06-30T22:39:57.944776300\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭标题无法确认暴力恐怖意图，\'Hit\'和\'Kill\'在流行音乐中属常规隐喻用法，符合豁免情形\",\"startedAt\":\"2026-06-30T22:39:53.969266\",\"finishedAt\":\"2026-06-30T22:40:00.650202900\",\"durationMs\":6680},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":45,\"reason\":\"仅凭标题\'Hit You With that Du Du Du\'无法确证色情低俗，属边界联想，置信度受限于无歌词证据\",\"startedAt\":\"2026-06-30T22:39:55.071726400\",\"finishedAt\":\"2026-06-30T22:39:59.211644400\",\"durationMs\":4139},{\"agentName\":\"AntiSocial\",\"displayName\":\"反社会\",\"order\":40,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T22:39:58.149221800\",\"finishedAt\":\"2026-06-30T22:40:05.234060900\",\"durationMs\":7084}],\"judge\":{\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":45,\"reason\":null,\"startedAt\":\"2026-06-30T22:40:05.513310400\",\"finishedAt\":\"2026-06-30T22:40:11.050037400\",\"durationMs\":5536},\"finishedAt\":\"2026-06-30T22:40:11.398581800\",\"finalStatus\":3,\"finalVerdict\":-2,\"finalConfidence\":45}', 4, 1, 1, NULL, '2026-06-30 22:40:49', '2026-06-30 22:39:52', '2026-06-30 22:40:11');
INSERT INTO `track_review_records` VALUES (2071967099527241729, 2071967094238224386, 'The Happiest Girl', 'Black Pink', 'Kill This Love', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'The Happiest Girl\'、歌手 \'Black Pink\'、专辑名 \'Kill This Love\' 均为英文，属流行音乐常规命名，无中文政治敏感字词；标题与专辑名均未出现国家、政权、领土、领导人或重大政治事件相关词汇，无法指向任何反国家、颠覆政权、主权错误表述、领导人侮辱或敏感事件不当评论。根据审核原则，仅凭元信息（无歌词）无法构成对四条标准的明确命中；\'Kill This Love\' 虽含动词 \'Kill\'，但属常见情感隐喻（如终结一段感情），在K-pop语境中广泛使用，不构成政治暗示；\'The Happiest Girl\' 为典型情感主题表达，无政治语义负载。因此，四条标准均无证据支持命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭专辑名 \'Kill This Love\' 中的 \'Kill\' 属常见情感隐喻，无其他敏感信息，证据不足且符合豁免情形\",\"analysis\":\"仅提供元信息：歌曲标题 \'The Happiest Girl\'、歌手 \'Black Pink\'、专辑名 \'Kill This Love\'。其中 \'Kill This Love\' 含动词 \'Kill\'，但该短语为常见英语习语式表达，意指‘终结这段感情’，属情感隐喻范畴，在K-pop语境中广泛用于表现决绝的分手主题（如类似表达 \'Kill Me\' \'Kill Bill\' 均无现实暴力指向）。专辑及歌曲实际内容为流行爱情叙事，无任何恐怖组织标识、口号、血腥描写或暴力煽动性表述；标题未含恐怖主义相关术语，亦无极端行为暗示。根据审核原则，\'歌名含敏感字眼但语境正常（情感隐喻）不应直接判 FAIL，需结合歌词综合判断\'，而本例无歌词，证据极度有限，无法确认是否存在批判视角或艺术豁免语境，故无法满足任一标准的命中条件。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'The Happiest Girl\' 为中性情感表达，字面意为\'最快乐的女孩\'，无露骨性描写或明显性暗示（未命中标准1）；无任何侮辱性词汇或指向特定群体的贬损表述（未命中标准2）；标题未涉及违法、吸毒、嫖娼等行为导向，亦无鼓吹或美化此类行为的语义（未命中标准3）；\'Happiest Girl\'属常见积极情感表述，非以低俗博眼球或粗鄙表达，具有常规审美与传播合理性（未命中标准4）。因歌词缺失，仅依据标题判断，而该标题在常规语境中无色情低俗歧义，亦无历史/文化/艺术语境下的负面指涉，属安全表达。但根据审核原则\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，故置信度上限受限。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'The Happiest Girl\' 为中性情感表达，字面含义指向积极情绪（幸福），无反社会、反人类语义；未含种族/民族/宗教/性别指向性词汇，无法构成仇恨或歧视煽动；无极端主义意识形态关键词（如\'净化\'\'消灭\'\'圣战\'\'绝对服从\'等）；未暗示违法犯罪或破坏公共秩序。标题属常见流行音乐命名惯例，与专辑名 \'Kill This Love\' 形成反讽张力，但\'Kill This Love\'在K-pop语境中普遍理解为终结不良情感关系的隐喻表达，属情感叙事范畴，非真实暴力倡导。根据审核原则：\'歌名含敏感字眼但语境正常（如历史题材、情感隐喻）不应直接判 FAIL\'，且歌词缺失，仅凭元信息无法支撑任何标准命中。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"四个维度均判 PASS，confidence 均为 60。PoliticalSensitivity 维度指出 \'Kill This Love\' 中的 \'Kill\' 属情感隐喻，无政治语义负载；ViolenceTerror 维度强调该用法在 K-pop 中属常见习语，无现实暴力或恐怖主义指向；ExplicitContent 维度确认标题无性暗示、侮辱、违法导向或低俗表达；AntiSocial 维度亦认定其无仇恨煽动、极端意识形态或反社会语义。四者分析逻辑一致、互为印证：均基于元信息（无歌词）+ 跨文化语境常识（K-pop 表达惯例）+ 隐喻豁免原则作出审慎判断。未出现任一维度报 FAIL，故无需触发一票否决、过度敏感纠偏或多维度共振规则；亦无 PENDING 状态。所有维度 confidence 均为 60，符合‘无歌词时 confidence 不超过 60’的内部约束，属合理上限，无需下调。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2071967099527241729,\"trackId\":2071967094238224386,\"trackTitle\":\"The Happiest Girl\",\"startedAt\":\"2026-06-30T22:40:26.775853\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":4,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":null,\"finishedAt\":\"2026-06-30T22:40:31.009742300\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭专辑名 \'Kill This Love\' 中的 \'Kill\' 属常见情感隐喻，无其他敏感信息，证据不足且符合豁免情形\",\"startedAt\":\"2026-06-30T22:40:27.164825300\",\"finishedAt\":\"2026-06-30T22:40:33.853927700\",\"durationMs\":6689},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\