INSERT INTO `track_review_records` VALUES (2071986332490973185, 2071986330238631937, '测试歌曲1', 'Kun', '测试', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题\'测试歌曲1\'、歌手名\'Kun\'、专辑名\'测试\'均为中性通用词汇，无任何政治指向性；无歌词内容，无法从中提取涉及反国家、颠覆政权、领土主权、领导人侮辱或敏感事件评论的表述；根据审核原则，仅凭元信息且无敏感字眼时，不构成对任一审核标准的明确命中；\'测试\'属常见非政治语境用词，不暗示或关联任何政治敏感含义。\",\"fail\":false,\"pending\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题为\'测试歌曲1\'，歌手为\'Kun\'，专辑为\'测试\'，均无任何暴力、恐怖主义、极端行为、血腥描写、煽动暴力或恐怖组织相关字眼或暗示。歌词明确标注为\'无歌词，仅审核元信息\'，根据审核原则，当没有歌词时仅凭标题等元信息判断，confidence 不超过 60。所有元信息内容中未出现任何符合标准1-4的直接表达或明确暗示，亦无敏感字眼（如\'血\'\'杀\'\'炸\'\'恐\'等），因此四条标准均未命中。\",\"fail\":false,\"pending\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法构成色情低俗等违规证据，符合\'无歌词时confidence不超过60\'的要求\",\"analysis\":\"歌曲标题\'测试歌曲1\'、歌手\'Kun\'、专辑\'测试\'均为中性、无敏感语义的常规命名，不含色情低俗词汇、侮辱性用语、违法诱导表述或庸俗化表达。根据审核原则，当无歌词且仅依赖元信息时，不得基于单字或空泛联想判定违规；\'测试\'为通用技术/创作术语，\'Kun\'为常见姓名缩写或艺名，均无明确不良语境支撑。因此，四条审核标准均无命中证据。\",\"fail\":false,\"pending\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌词为\'无歌词，仅审核元信息\'，因此仅能依据歌曲标题\'测试歌曲1\'、歌手\'Kun\'、专辑\'测试\'进行判断。标题与专辑名均为中性通用词汇，不含任何敏感字眼（如\'灭绝\'\'清除\'\'仇恨\'\'颠覆\'等），亦无指向特定群体或意识形态的暗示；歌手名\'Kun\'为常见姓名缩写，无已知负面关联。根据审核原则：\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'；且\'歌名/专辑名含敏感字眼但语境正常（如历史题材、情感隐喻）不应直接判 FAIL\'——而本例中标题与专辑名甚至不包含敏感字眼，完全无法支撑任何一条审核标准的命中。因此，四条标准均无证据支持命中。\",\"fail\":false,\"pending\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"四个维度均判为PASS，confidence均为60，且各自analysis逻辑一致、证据充分：政治敏感性维度确认元信息无任何政治指向；暴力恐怖维度明确排除暴力/恐怖相关字眼及暗示；色情低俗维度强调无歌词且元信息中性，拒绝空泛联想；反社会维度指出无仇恨、颠覆等敏感词，亦无语境支撑。四者均严格遵循\'无歌词时confidence不超60\'的规则，未出现过度敏感（如将\'测试\'误读为隐喻、将\'Kun\'强行关联负面事件等），不存在需纠偏的误判情形；无任一维度报FAIL或PENDING，未触发一票否决、多维度共振或人工介入条件。\",\"fail\":false,\"pending\":false,\"pass\":true}}', '{\"recordId\":2071986332490973185,\"trackId\":2071986330238631937,\"trackTitle\":\"测试歌曲1\",\"startedAt\":\"2026-06-30T23:56:52.140278400\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":4,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":null,\"finishedAt\":\"2026-06-30T23:56:55.293164\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T23:56:52.281010200\",\"finishedAt\":\"2026-06-30T23:56:55.632376200\",\"durationMs\":3351},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅凭元信息无法构成色情低俗等违规证据，符合\'无歌词时confidence不超过60\'的要求\",\"startedAt\":\"2026-06-30T23:56:55.409265800\",\"finishedAt\":\"2026-06-30T23:56:58.589857100\",\"durationMs\":3180},{\"agentName\":\"AntiSocial\",\"displayName\":\"反社会\",\"order\":40,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T23:56:55.754546\",\"finishedAt\":\"2026-06-30T23:57:01.283616400\",\"durationMs\":5529}],\"judge\":{\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-06-30T23:57:01.406299900\",\"finishedAt\":\"2026-06-30T23:57:04.902208500\",\"durationMs\":3495},\"finishedAt\":\"2026-06-30T23:57:05.115563700\",\"finalStatus\":3,\"finalVerdict\":-2,\"finalConfidence\":60}', 4, 1, 1, NU