INSERT INTO `track_review_records` VALUES (2071998031092744194, 2071998028865568769, '1', 'Kun', '测试', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅审核元信息，无敏感词或可疑语境，符合置信度上限60要求\",\"analysis\":\"歌曲标题为\'1\'，歌手名为\'Kun\'，专辑名为\'测试\'，均无明确政治语义或敏感指向；无歌词内容可供分析，无法从中提取反国家、颠覆政权、领土主权错误、领导人侮辱或敏感事件不当评论等表述。根据审核原则，仅凭标题、歌手名、专辑名等元信息且无敏感字眼，无法构成任何一条审核标准的命中证据。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题为\'1\'，歌手为\'Kun\'，专辑为\'测试\'，无歌词内容。标题\'1\'为纯数字，无任何暴力、恐怖主义、极端行为、血腥、煽动性或恐怖组织相关语义；歌手名\'Kun\'与已知恐怖组织名称、标识、口号无关联；专辑名\'测试\'属中性通用词，不携带任何敏感含义。所有元信息均未出现审核标准中规定的关键词、符号、隐喻或暗示。根据审核原则：\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，且此处元信息完全无敏感指向，未命中任一标准。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题为\'1\'，属纯数字，无语义指向，不构成色情、低俗、侮辱性、不良价值观或庸俗化表达；歌手名\'Kun\'为常见英文名/艺名（如EXO成员吴亦凡曾用艺名KUN），无贬义或敏感含义；专辑名\'测试\'为中性功能型词汇，常用于技术验证场景，无任何违规语义。所有元信息均无露骨性描写、性暗示、谩骂、违法鼓吹或粗鄙表达。根据审核原则：\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题为\'1\'，歌手为\'Kun\'，专辑为\'测试\'，歌词标注为\'无歌词，仅审核元信息\'。标题\'1\'为纯数字，无语义指向，不构成反社会、反人类言论（标准1）；未含任何种族/民族/宗教/性别相关词汇，无法构成仇恨或歧视煽动（标准2）；无意识形态表述，不涉及极端思想传播（标准3）；标题、歌手名、专辑名均未鼓吹违法犯罪或破坏公共秩序（标准4）。根据审核原则，\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，且所有元信息均为中性、无敏感语义的常规标识，无任何命中证据。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"四个维度均判为PASS，confidence均为60。PoliticalSensitivity维度指出标题\'1\'、歌手\'Kun\'、专辑\'测试\'无任何政治语义或敏感指向，分析合理，未出现隐喻联想或歌名过敏；ViolenceTerror维度确认纯数字标题与中性元信息不构成暴力恐怖关联，判断稳健；ExplicitContent维度正确识别\'1\'为无语义符号、\'Kun\'为常见艺名、\'测试\'为功能型词汇，未过度解读；AntiSocial维度全面覆盖反社会四类标准，均无命中依据。所有维度均严格遵循\'无歌词时仅审元信息，confidence≤60\'的规则，且无一存在过度敏感问题（如将数字\'1\'强行关联敏感事件、将\'Kun\'误判为敏感词等），故无需下调权重或纠偏。四维全部PASS，符合\'全PASS\'裁决条件。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2071998031092744194,\"trackId\":2071998028865568769,\"trackTitle\":\"1\",\"startedAt\":\"2026-07-01T00:43:21.297870300\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":4,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅审核元信息，无敏感词或可疑语境，符合置信度上限60要求\",\"startedAt\":\"2026-07-01T00:43:21.437512400\",\"finishedAt\":\"2026-07-01T00:43:24.532256400\",\"durationMs\":3094},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":null,\"finishedAt\":\"2026-07-01T00:43:25.329517100\",\"durationMs\":null},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-07-01T00:43:24.659483800\",\"finishedAt\":\"2026-07-01T00:43:28.137891900\",\"durationMs\":3478},{\"agentName\":\"AntiSocial\",\"displayName\":\"反社会\",\"order\":40,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-07-01T00:43:25.447423100\",\"finishedAt\":\"2026-07-01T00:43:30.469589200\",\"durationMs\":5022}],\"judge\":{\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-07-01T00:43:30.583226900\",\"finishedAt\":\"2026-07-01T00:43:34.946729100\",\"durationMs\":4363},\"finishedAt\":\"2026-07-01T00:43:35.144394