INSERT INTO `track_review_records` VALUES (2072170226590883842, 2072170221234757633, '测试歌曲1', 'Kun', '测试', NULL, -2, 49, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":49},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":\"仅审核元信息，无敏感内容，但confidence受限于无歌词证据，按规则上限设为60\",\"analysis\":\"歌曲标题\'测试歌曲1\'、歌手\'Kun\'、专辑\'测试\'均为通用占位符名称，无明确政治指向性；无歌词内容，无法从中提取任何涉及反国家、颠覆政权、领土主权错误表述、领导人侮辱或敏感事件不当评论的文本证据；根据审核原则，仅凭元信息（标题/歌手/专辑）且无敏感语义时，不构成对任一审核标准的命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题为\'测试歌曲1\'，歌手为\'Kun\'，专辑为\'测试\'，均无任何暴力、恐怖主义、极端行为、血腥描写、煽动暴力或恐怖组织相关字眼；歌词明确标注为\'无歌词，仅审核元信息\'，因此无文本内容可供分析暴力恐怖倾向；根据审核原则，没有歌词或歌词为纯LRC元标签时，仅凭标题等元信息判断，confidence不超过60；所有四条审核标准均缺乏命中证据：1) 标题、歌手、专辑未宣扬暴力或恐怖主义；2) 无任何血腥或极端行为描写；3) 无煽动暴力冲突表述；4) 无恐怖组织标识、口号或宣传语。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":49,\"analysis\":\"歌曲标题\'测试歌曲1\'、歌手名\'Kun\'、专辑名\'测试\'均为中性、无敏感语义的通用词汇，未包含任何色情、低俗、侮辱性、违法或庸俗化表达。根据审核原则，当无歌词且仅凭元信息判断时，confidence 不超过 60；当前所有元信息均无违规字眼或可疑语境，无法支持任何一条审核标准的命中。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题\'测试歌曲1\'、歌手\'Kun\'、专辑\'测试\'均为中性无敏感语义的元信息，未包含任何反社会、反人类言论（标准1）；未出现针对种族/民族/宗教/性别等群体的指称或贬损性表述，无法构成仇恨煽动（标准2）；无意识形态关键词或极端主义符号，不涉及极端思想传播（标准3）；标题与署名均未鼓吹违法犯罪或破坏公共秩序，亦无违背社会核心价值观的明确表达（标准4）。根据审核原则，\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，当前全部元信息均无违规迹象，但因缺乏实质性文本证据，判断依据有限。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":49,\"analysis\":\"