INSERT INTO `track_review_records` VALUES (2072175121389805570, 2072175118961303553, '测试歌曲11', '测试歌手', '测试', NULL, 1, 100, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":100},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":100},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":100},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":100}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":\"无政治敏感相关内容，政治敏感审核通过\",\"analysis\":\"歌曲标题\'测试歌曲11\'、歌手名\'测试歌手\'、专辑名\'测试\'均为通用占位符性质命名，不含任何政治实体、领导人、领土名称、历史事件或敏感符号；无歌词可供分析；所有元信息均未出现反国家、颠覆政权、领土主权错误表述、领导人侮辱性用语或政治敏感事件相关词汇；不构成对宪法秩序的否定、不涉及地图认知或主权归属表述、无人身攻击意图、未关联任何重大政治事件。因此，四条审核标准均未命中。\",\"fail\":false,\"pending\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":\"无暴力恐怖相关内容，暴力恐怖审核通过\",\"analysis\":\"歌曲标题\'测试歌曲11\'、歌手\'测试歌手\'、专辑\'测试\'均为通用测试用占位符，不含任何暴力、恐怖主义、极端行为、血腥描写、煽动暴力或恐怖组织相关字眼；歌词明确标注\'无歌词，仅审核元信息\'，且元信息中无任何符合审核标准1)-4)的表述或暗示；所有字段均与暴力恐怖维度完全无关，不涉及宣扬、描绘、煽动或展示任何违规内容。\",\"fail\":false,\"pending\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":\"无色情低俗相关内容，色情低俗审核通过\",\"analysis\":\"歌曲标题\'测试歌曲11\'、歌手名\'测试歌手\'、专辑名\'测试\'均为通用测试用占位符，不含任何色情、低俗、侮辱性、不良价值观或庸俗化表达的字眼或暗示；歌词明确标注\'无歌词，仅审核元信息\'，且所有元信息均与色情低俗维度完全无关；无露骨性描写、无性暗示、无侮辱性语言、无不健康价值观、无庸俗化表达，亦无任何需豁免的艺术表达或语境依赖。\",\"fail\":false,\"pending\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":100,\"reason\":\"无反社会反人类相关内容，反社会反人类审核通过\",\"analysis\":\"歌曲标题\'测试歌曲11\'、歌手名\'测试歌手\'、专辑名\'测试\'均为通用测试性命名，不含任何反社会、反人类言论；无歌词，故无法检出煽动仇恨、歧视、极端思想或违背社会核心价值观的表达；所有元信息均未涉及种族/民族/宗教/性别等敏感维度，亦无违法犯罪、破坏公共秩序等暗示；内容明确标注为测试用途，与反社会反人类维度完全无关。\",\"fail\":false,\"pending\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":100,\"analysis\":\"四个维度（PoliticalSensitivity、Violence