INSERT INTO `track_review_records` VALUES (2072330441158324226, 2071965884630310913, 'Get Up', 'New Jeans', 'New Jeans Album', NULL, -2, 60, NULL, '{\"dimensionSummary\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60}],\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Get Up\' 为常见英文短语，意为起身、振作、行动等，属中性积极表达；歌手名 \'New Jeans\' 为韩国流行音乐组合名称，指代牛仔裤，无政治含义；专辑名 \'New Jeans Album\' 为常规命名方式。所有元信息均未出现任何中文或外文的反国家、颠覆政权、领土主权错误、领导人侮辱、敏感事件不当评论等表述。根据审核原则，仅凭标题/艺人名等元信息且无歌词时，无法构成明确政治敏感内容，不满足任一命中标准。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ViolenceTerror\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Get Up\' 为常见英文短语，含义为起身、振作、唤醒等，无暴力恐怖相关语义；歌手 \'New Jeans\' 为韩国流行音乐团体，名称源自牛仔裤（jeans），属时尚文化符号，与恐怖主义或暴力无关；专辑名 \'New Jeans Album\' 同样仅指向艺人身份及作品归属，不含任何敏感标识、口号或宣传语。所有元信息中未出现暴力、血腥、恐怖组织相关词汇，亦无歧义性暗示。根据审核原则，仅凭标题/艺人名等元信息且无歌词时，confidence 不超过 60；此处无任何命中证据，四条标准均未触发。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"ExplicitContent\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Get Up\' 为常见英文短语，含义包括\'起床\'\'振作起来\'\'起身\'等，属中性日常表达；歌手名 \'New Jeans\' 指牛仔裤品牌或青春意象，无色情低俗指向；专辑名 \'New Jeans Album\' 与歌手名一致，属常规命名逻辑。四条审核标准均需基于具体内容（如歌词）或明确语境判断：1) 标题无露骨性描写或明显性暗示，\'Get Up\' 在音乐语境中常见于舞曲/励志类作品（如Beyoncé《Get Up》），不构成色情低俗；2) 无任何针对群体的谩骂或人格侮辱用语；3) 无鼓吹违法、吸毒、嫖娼等行为的表述；4) \'Get Up\' 非粗鄙表达，亦非以低俗博眼球的庸俗化措辞。因无歌词，仅凭元信息无法支撑任何标准命中，且标题本身无歧义性低俗联想，不符合\'仅凭单字联想\'情形（如\'操\'\'屄\'等字），故不满足任一命中条件。\",\"pending\":false,\"fail\":false,\"pass\":true},{\"agentName\":\"AntiSocial\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"歌曲标题 \'Get Up\' 为常见英文短语，含义为\'起身、振作、行动起来\'，属中性积极表达；歌手名 \'New Jeans\' 为时尚品牌名称的借用，无政治或意识形态指向；专辑名 \'New Jeans Album\' 同样无敏感语义。所有元信息均未出现反社会、反人类表述（标准1），未含任何针对种族/民族/宗教/性别等群体的贬损、排斥或清除性词汇（标准2），未出现极端主义术语、口号或意识形态标识（标准3），亦未暗示或鼓吹违法犯罪、暴力破坏等行为（标准4）。根据审核原则，\'没有歌词或歌词为纯 LRC 元标签时，仅凭标题等元信息判断，confidence 不超过 60\'，且所有元信息均无明确违规证据。\",\"pending\":false,\"fail\":false,\"pass\":true}],\"judge\":{\"agentName\":\"ReviewJudge\",\"verdict\":\"PASS\",\"confidence\":60,\"analysis\":\"四个维度均判 PASS，confidence 均为 60，且各自 analysis 均逻辑清晰、证据充分：PoliticalSensitivity 指出 \'Get Up\' 为中性积极短语，无政治隐喻；ViolenceTerror 明确排除暴力恐怖关联，强调名称源自时尚文化；ExplicitContent 合理辨析 \'Get Up\' 在音乐语境中的常规用法（如Beyoncé同名曲），否定低俗联想；AntiSocial 正确识别其积极行动导向，无反社会语义。四者均未出现过度敏感问题（如未将 \'Get Up\' 错解为煽动性口号，亦未因 \'Jeans\' 联想不当文化符号），无需下调权重。无任何维度报 FAIL 或 PENDING，不触发一票否决、多维度共振或人工介入条件。\",\"pending\":false,\"fail\":false,\"pass\":true}}', '{\"recordId\":2072330441158324226,\"trackId\":2071965884630310913,\"trackTitle\":\"Get Up\",\"startedAt\":\"2026-07-01T22:44:14.094671700\",\"stage\":\"FINISHED\",\"totalDimensions\":4,\"completedDimensions\":4,\"dimensions\":[{\"agentName\":\"PoliticalSensitivity\",\"displayName\":\"政治敏感\",\"order\":10,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":null,\"finishedAt\":\"2026-07-01T22:44:17.972628300\",\"durationMs\":null},{\"agentName\":\"ViolenceTerror\",\"displayName\":\"暴力恐怖\",\"order\":20,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-07-01T22:44:14.310735800\",\"finishedAt\":\"2026-07-01T22:44:18.339696500\",\"durationMs\":4028},{\"agentName\":\"ExplicitContent\",\"displayName\":\"色情低俗\",\"order\":30,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-07-01T22:44:15.711991600\",\"finishedAt\":\"2026-07-01T22:44:20.609956200\",\"durationMs\":4897},{\"agentName\":\"AntiSocial\",\"displayName\":\"反社会\",\"order\":40,\"status\":\"DONE\",\"verdict\":\"PASS\",\"confidence\":60,\"reason\":null,\"startedAt\":\"2026-07-01T22:44:18.134660500\",\"finishedAt\":\"2026-07-01T22:44:22.001248\",\"durationMs\":3866}],\"judge\":{\"status\":\"DONE\"