-- ----------------------------
-- Table structure for user_periodic_reports
-- ----------------------------
DROP TABLE IF EXISTS `user_periodic_reports`;
CREATE TABLE `user_periodic_reports`  (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `user_id` bigint NOT NULL COMMENT '用户 ID',
  `period_type` tinyint NOT NULL COMMENT '1=周报 2=月报',
  `period_start` date NOT NULL COMMENT '周期起始日(周报=周一,月报=1号)',
  `period_end` date NOT NULL COMMENT '周期结束日(周报=周日,月报=月末)',
  `stats_snapshot` json NOT NULL COMMENT '统计快照 JSON(冗余,避免统计层变更影响历史报告)',
  `llm_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'LLM 生成的总结文本',
  `mood_tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '心情标签, 逗号分隔',
  `highlights` json NULL COMMENT '重点时刻 JSON',
  `recommendations` json NULL COMMENT '推荐收听 JSON',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0=生成中 1=已生成 2=失败 3=无数据',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `generated_at` datetime NULL DEFAULT NULL COMMENT 'LLM 生成完成时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_period`(`user_id` ASC, `period_type` ASC, `period_start` ASC) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_period`(`period_type` ASC, `period_start` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户周期总结报告' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_periodic_reports
-- ----------------------------

-- ----------------------------
-- Table structure for user_preference_vectors
-- ----------------------------
DROP TABLE IF EXISTS `user_preference_vectors`;
CREATE TABLE `user_preference_vectors`  (
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `total_play_count` int NOT NULL DEFAULT 0 COMMENT '历史总播放次数',
  `active_days` int NOT NULL DEFAULT 0 COMMENT '近30天活跃天数',
  `confidence_score` decimal(3, 2) NOT NULL DEFAULT 0.00 COMMENT '画像置信度 (0~1, 基于行为量计算)',
  `fusion_ratio` decimal(3, 2) NOT NULL DEFAULT 0.70 COMMENT '长期画像融合权重 (0~1, 剩余为短期权重)',
  `long_term_genre` json NULL COMMENT '长期流派偏好',
  `long_term_artist` json NULL COMMENT '长期艺人偏好',
  `long_term_emotion` json NULL COMMENT '长期情绪标签偏好',
  `long_term_scene` json NULL COMMENT '长期场景标签偏好',
  `long_term_updated_at` datetime NULL DEFAULT NULL COMMENT '长期画像计算时间',
  `short_term_genre` json NULL COMMENT '短期流派偏好',
  `short_term_artist` json NULL COMMENT '短期艺人偏好',
  `short_term_emotion` json NULL COMMENT '短期情绪标签偏好',
  `short_term_scene` json NULL COMMENT '短期场景标签偏好',
  `short_term_updated_at` datetime NULL DEFAULT NULL COMMENT '短期画像计算时间',
  `negative_genre` json NULL COMMENT '不喜欢的流派 (权重为负)',
  `negative_artist` json NULL COMMENT '不喜欢的艺人 (权重为负)',
  `negative_updated_at` datetime NULL DEFAULT NULL COMMENT '负向画像计算时间',
  `profile_version` int NOT NULL DEFAULT 1 COMMENT '画像算法版本 (1=V1, 2=V2)',
  `calculated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '本次画像计算时间戳',
  `data_snapshot` json NULL COMMENT '计算依据快照 (如: 最近30天统计)',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录最后更新时间',
  PRIMARY KEY (`user_id`) USING BTREE,
  INDEX `idx_calculated`(`calculated_at` ASC) USING BTREE COMMENT '用于监控计算时效性'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_preference_vectors
-- ----------------------------

-- ----------------------------
-- Table structure for user_profiles
-- ----------------------------
DROP TABLE IF EXISTS `user_profiles`;
CREATE TABLE `user_profiles`  (
  `user_id` bigint NOT NULL COMMENT '用户ID主键',
  `favorite_genres` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '喜欢的流派(逗号分隔)',
  `favorite_artists` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '喜欢的歌手(逗号分隔)',
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Agent维护的用户偏好详细总结',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Agent智能对话-用户画像表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_profiles
-- ----------------------------

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `id` bigint NOT NULL COMMENT '雪花算法唯一ID',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `avatar_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `country` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CN' COMMENT '国家代码 (ISO-3166 2位代码)',
  `product` int NOT NULL DEFAULT 0 COMMENT '产品等级/订阅类型: 0为免费用户(free), 1为会员用户(premium)',
  `status` int NOT NULL DEFAULT 0 COMMENT '用户状态: 0为正常(active), -1为封禁(banned)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `users_email_key`(`email` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of users
-- ----------------------------
